from pathlib import Path
from docx import Document
from docx.shared import Cm, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

out=Path('contracts_for_legal_review'); out.mkdir(exist_ok=True)

def rtl(doc,text,kind='body'):
    par=doc.add_paragraph()
    par.alignment=WD_ALIGN_PARAGRAPH.LEFT
    f=par.paragraph_format; f.space_after=Pt(6); f.line_spacing=1.18
    if kind in ('title','heading'): f.keep_with_next=True; f.space_before=Pt(9)
    par._p.get_or_add_pPr().append(OxmlElement('w:bidi'))
    run=par.add_run(text); rpr=run._r.get_or_add_rPr(); rpr.append(OxmlElement('w:rtl'))
    run.font.name='Arial'; rpr.rFonts.set(qn('w:cs'),'Arial'); run.font.color.rgb=RGBColor(0,0,0)
    size=19 if kind=='title' else 13 if kind=='heading' else 10.5
    run.font.size=Pt(size)
    cs=OxmlElement('w:szCs'); cs.set(qn('w:val'),str(int(size*2))); rpr.append(cs)
    if kind in ('title','heading','label'): rpr.append(OxmlElement('w:bCs'))
    run.bold=kind in ('title','heading','label')
    return par

def sec(doc,title,lines):
    rtl(doc,title,'heading')
    for line in lines: rtl(doc,line)

